<script setup>
import {computed} from 'vue'
const props=defineProps({plan:{type:Object,required:true},selected:Boolean,disabled:Boolean,readonly:Boolean,currency:{type:String,default:'LKR'}})
const emit=defineEmits(['choose'])
const name=computed(()=>props.plan.plan||props.plan.name||'Individual')
const amount=computed(()=>props.plan.monthly_minor??(props.plan.monthly_lkr==null?null:props.plan.monthly_lkr*100))
const money=computed(()=>amount.value==null?'Price unavailable':new Intl.NumberFormat('en-LK',{style:'currency',currency:props.currency,maximumFractionDigits:0}).format(amount.value/100))
</script>
<template><article class="shared-plan" :class="[name.toLowerCase(),{selected}]"><header><h3>{{name}}</h3><span v-if="selected" class="selected-label">✓ Selected</span></header><p v-if="plan.description">{{plan.description}}</p><div class="membership-card" aria-hidden="true"><strong>sisu.</strong><span class="card-chip"></span><div><b>{{name}}</b><small>LEARNVERSE</small></div></div><div class="shared-price">{{money}}<small>/ month base fee</small></div><ul><li v-for="(feature,i) in plan.card_features||[]" :key="i"><span aria-hidden="true">✓</span>{{feature}}</li></ul><button v-if="!readonly" type="button" :disabled="disabled||selected||amount==null" @click="emit('choose',name)">{{selected?'Selected':'Choose plan'}}</button><slot/></article></template>
